"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[160],{6219(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>p,frontMatter:()=>l,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"part5-deep-learning-and-llms/forecasting-sequence-data","title":"Forecasting and Sequence Data (Time Series)","description":"A standalone tutorial on what sequence data is, how to shape it for ML, what \u201cforecasting\u201d really means, and how to avoid the most common multi-step forecasting mistake: data leakage through future inputs.","source":"@site/docs/part5-deep-learning-and-llms/08-forecasting-sequence-data.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/08-forecasting-sequence-data","permalink":"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":8,"frontMatter":{"title":"Forecasting and Sequence Data (Time Series)","slug":"/part5-deep-learning-and-llms/08-forecasting-sequence-data","description":"A standalone tutorial on what sequence data is, how to shape it for ML, what \u201cforecasting\u201d really means, and how to avoid the most common multi-step forecasting mistake: data leakage through future inputs.","sidebar_label":"8. Forecasting and sequence data","pagination_label":"8. Forecasting and sequence data","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"7. CNN dropout and train/eval","permalink":"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval"},"next":{"title":"9. Autoregressive linear model","permalink":"/tutorials/part5-deep-learning-and-llms/09-autoregressive-linear-model"}}');var s=n(4848),r=n(8453),i=n(8172);const o=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/08-forecasting-sequence-data.html","route":"/part5-deep-learning-and-llms/08-forecasting-sequence-data","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Forecasting & Sequence Data (Time Series)","title":"Forecasting and Sequence Data (Time Series)","description":"A standalone tutorial on what sequence data is, how to shape it for ML, what \u201cforecasting\u201d really means, and how to avoid the most common multi-step forecasting mistake: data leakage through future inputs.","readingMinutes":9,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-counts-as-sequence-data","label":"1) What counts as sequence data?"},{"id":"2-what-makes-time-series-different-from-ordinary-tabular-ml","label":"2) What makes time series different from ordinary tabular ML?"},{"id":"3-how-to-represent-sequence-data-n-times-t-times-d","label":"3) How to represent sequence data: \\\\(N \\\\times T \\\\times D\\\\)"},{"id":"4-forecast-origin-lookback-target-and-horizon","label":"4) Forecast origin, lookback, target, and horizon"},{"id":"5-turning-a-long-series-into-supervised-learning-windows","label":"5) Turning a long series into supervised learning windows"},{"id":"6-a-dumb-but-great-baseline-linear-regression-as-an-ar-model","label":"6) A \u201cdumb but great\u201d baseline: linear regression as an AR model"},{"id":"7-exogenous-variables-what-is-known-in-the-future","label":"7) Exogenous variables: what is known in the future?"},{"id":"8-the-most-common-forecasting-mistake-leaking-future-inputs","label":"8) The most common forecasting mistake: leaking future inputs"},{"id":"9-forecasting-strategies-for-h-1","label":"9) Forecasting strategies for \\\\(H>1\\\\)"},{"id":"10-minimal-correct-forecasting-code-baseline-ar-with-recursion","label":"10) Minimal, correct forecasting code: baseline AR with recursion"},{"id":"11-evaluation-one-split-is-a-start-backtesting-is-better","label":"11) Evaluation: one split is a start, backtesting is better"},{"id":"12-where-rnns-fit-next","label":"12) Where RNNs fit next"}],"html":"<main class=\\"wrap\\">\\n    \\n    <p class=\\"sub\\">\\n      A standalone tutorial on what sequence data is, how to shape it for ML, what \u201cforecasting\u201d really means,\\n      and how to avoid the most common multi-step forecasting mistake: data leakage through future inputs.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <span class=\\"badge\\">Key idea</span>\\n      <p>\\n        Sequences are not just \u201clots of rows.\u201d They have <strong>order</strong>. The value at time \\\\(t\\\\) is often related to\\n        values at \\\\(t-1, t-2, \\\\dots\\\\). Forecasting is the discipline of exploiting that ordered dependence to predict values\\n        that have not happened yet.\\n      </p>\\n    </div>\\n\\n    <h2 id=\\"1-what-counts-as-sequence-data\\">1) What counts as sequence data?</h2>\\n    <div class=\\"grid\\">\\n      <div class=\\"card\\">\\n        <h3 id=\\"time-series-values-indexed-by-time\\">Time series: values indexed by time</h3>\\n        <ul>\\n          <li><strong>Finance:</strong> prices, returns, volume, spreads sampled every minute/day.</li>\\n          <li><strong>Weather:</strong> temperature, rain, humidity, pressure, wind over time.</li>\\n          <li><strong>Audio:</strong> a waveform is amplitude measured over time.</li>\\n          <li><strong>Sensor streams:</strong> accelerometers, ECG, machines, IoT, clickstreams, logs.</li>\\n        </ul>\\n        <p class=\\"mini\\">\\n          The sequence axis is the time axis: rows arrive in order and nearby rows tend to be statistically related.\\n        </p>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <h3 id=\\"example-time-series-plot\\">Example time series plot</h3>\\n        <figure>\\n          <img src=\\"/tutorials/images/external/COVID-19_Confirmed_Cases-d7a49434a6-fallback.svg\\" alt=\\"Example time series plot\\" style=\\"width:100%; height:auto; border:1px solid var(--border); border-radius:12px;\\">\\n          <figcaption>\\n            Any \u201cvalue vs time\u201d curve is a time series. Displayed as a local asset; source credit retained where applicable.\\n          </figcaption>\\n        </figure>\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"text-is-also-sequential-but-with-discrete-tokens\\">Text is also sequential, but with discrete tokens</h3>\\n      <p>\\n        A sentence is a sequence of tokens. Older ML often used <strong>bag-of-words</strong>: convert a document into a\\n        word-count vector and ignore order. That makes standard classifiers easy to use, but it destroys the sequential signal.\\n      </p>\\n      <div class=\\"callout tight\\">\\n        <p><strong>Why bag-of-words can fail:</strong> \u201cdog toy\u201d and \u201ctoy dog\u201d have the same word counts but different meaning.</p>\\n      </div>\\n      <p>\\n        Time-series forecasting and language modeling are not identical, but they share one deep idea: the next output depends\\n        on ordered context. Chapter 10 uses recurrent state for ordered context; Chapter 11 replaces that with attention.\\n      </p>\\n    </div>\\n\\n    <h2 id=\\"2-what-makes-time-series-different-from-ordinary-tabular-ml\\">2) What makes time series different from ordinary tabular ML?</h2>\\n    <div class=\\"grid\\">\\n      <div class=\\"card\\">\\n        <h3 id=\\"rows-are-not-exchangeable\\">Rows are not exchangeable</h3>\\n        <p>\\n          In ordinary tabular ML, you often treat rows as independent examples and shuffle them before training. In forecasting,\\n          shuffling can destroy the question. Training on 2025 and validating on 2020 is not a forecast.\\n        </p>\\n        <p class=\\"mini\\">\\n          The split must respect time: train on the past, validate/test on the future.\\n        </p>\\n      </div>\\n      <div class=\\"card\\">\\n        <h3 id=\\"the-data-generating-process-can-change\\">The data-generating process can change</h3>\\n        <p>\\n          Time series can have <strong>trend</strong>, <strong>seasonality</strong>, <strong>cycles</strong>, structural breaks,\\n          missing periods, outliers, and changing variance. A model trained on one regime can fail when the future regime changes.\\n        </p>\\n        <p class=\\"mini\\">\\n          This is why backtesting over multiple forecast origins is often more trustworthy than one lucky split.\\n        </p>\\n      </div>\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 270\\" role=\\"img\\" aria-label=\\"Time series components: trend seasonality noise and events\\">\\n        <defs>\\n          <marker id=\\"ts-components-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">A forecast is trying to separate signal from time-dependent structure</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The future is not just the last value repeated; it may contain trend, seasonality, shocks, and noise.</text>\\n\\n        <polyline points=\\"70,190 135,178 200,164 265,150 330,138 395,124 460,110 525,98 590,84\\" fill=\\"none\\" stroke=\\"#0969da\\" stroke-width=\\"4\\"></polyline>\\n        <text x=\\"310\\" y=\\"218\\" class=\\"label\\" text-anchor=\\"middle\\">trend</text>\\n\\n        <path d=\\"M70 128 C105 82 140 82 175 128 S245 174 280 128 S350 82 385 128 S455 174 490 128 S560 82 595 128\\" fill=\\"none\\" stroke=\\"#8250df\\" stroke-width=\\"4\\"></path>\\n        <text x=\\"330\\" y=\\"78\\" class=\\"label\\" text-anchor=\\"middle\\">seasonality</text>\\n\\n        <circle cx=\\"665\\" cy=\\"124\\" r=\\"12\\" fill=\\"#cf222e\\"></circle>\\n        <path fill=\\"none\\" d=\\"M665 136 L665 184\\" stroke=\\"#cf222e\\" stroke-width=\\"3\\" marker-end=\\"url(#ts-components-arrow)\\"></path>\\n        <text x=\\"665\\" y=\\"214\\" class=\\"label\\" text-anchor=\\"middle\\">event / shock</text>\\n\\n        <g transform=\\"translate(755,96)\\">\\n          <rect x=\\"0\\" y=\\"0\\" width=\\"160\\" height=\\"92\\" rx=\\"14\\" fill=\\"#f6f8fa\\" stroke=\\"#d0d7de\\"></rect>\\n          <path d=\\"M18 46 L34 35 L50 59 L66 40 L82 53 L98 30 L114 62 L132 42 L146 50\\" fill=\\"none\\" stroke=\\"#1a7f37\\" stroke-width=\\"3\\"></path>\\n          <text x=\\"80\\" y=\\"122\\" class=\\"label\\" text-anchor=\\"middle\\">noise / residual</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        A useful baseline should make these ideas explicit: what repeats, what drifts, what is random, and what information is actually known at forecast time.\\n      </figcaption>\\n    </figure>\\n\\n    <h2 id=\\"3-how-to-represent-sequence-data-n-times-t-times-d\\">3) How to represent sequence data: \\\\(N \\\\times T \\\\times D\\\\)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        For non-sequential data you are used to \\\\(X \\\\in \\\\mathbb{R}^{N \\\\times D}\\\\): samples by features.\\n        For sequences, we add a <strong>time axis</strong>:\\n      </p>\\n      <p style=\\"font-size:1.05rem;\\">\\n        \\\\[\\n          X \\\\in \\\\mathbb{R}^{N \\\\times T \\\\times D}\\n        \\\\]\\n      </p>\\n      <ul>\\n        <li><strong>\\\\(N\\\\)</strong>: number of samples. Each sample is one sequence window.</li>\\n        <li><strong>\\\\(T\\\\)</strong>: number of time steps in the window. This is also called lookback, context length, or lag length.</li>\\n        <li><strong>\\\\(D\\\\)</strong>: number of features measured at each time step.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"concrete-examples-so-n-t-and-d-do-not-get-mixed-up\\">Concrete examples so \\\\(N\\\\), \\\\(T\\\\), and \\\\(D\\\\) do not get mixed up</h3>\\n      <ul>\\n        <li><strong>GPS commute tracking:</strong> each trip is one sample (\\\\(N\\\\)); each timestamp is one step (\\\\(T\\\\)); latitude/longitude means \\\\(D=2\\\\).</li>\\n        <li><strong>Single stock price:</strong> \\\\(D=1\\\\). If you slice the long series into windows of length \\\\(T\\\\), each window is one sample.</li>\\n        <li><strong>500 stocks:</strong> \\\\(D=500\\\\). Each time step contains a 500-dimensional market snapshot.</li>\\n        <li><strong>Brain electrodes:</strong> \\\\(D=\\\\) number of electrodes. With 1 kHz sampling for one second, \\\\(T=1000\\\\).</li>\\n      </ul>\\n      <p class=\\"mini\\">\\n        The axis order \\\\(N \\\\times T \\\\times D\\\\) is common in Python sequence modeling when `batch_first=True`.\\n      </p>\\n    </div>\\n\\n    <h2 id=\\"4-forecast-origin-lookback-target-and-horizon\\">4) Forecast origin, lookback, target, and horizon</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Forecasting starts from a <strong>forecast origin</strong>: the last time point you are allowed to know.\\n        You choose a <strong>lookback</strong> \\\\(T\\\\), then predict one or more future steps.\\n      </p>\\n      <ul>\\n        <li><strong>Lookback \\\\(T\\\\):</strong> how many past steps the model sees.</li>\\n        <li><strong>Target:</strong> the value you ask the model to predict.</li>\\n        <li><strong>Horizon \\\\(H\\\\):</strong> how far into the future you want predictions.</li>\\n      </ul>\\n      <p>\\n        If steps are hours and you forecast 7 days hourly, \\\\(H = 7 \\\\times 24 = 168\\\\).\\n        If steps are days and you forecast the next 5 days, \\\\(H=5\\\\).\\n      </p>\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 260\\" role=\\"img\\" aria-label=\\"Lookback forecast origin target and horizon timeline\\">\\n        <defs>\\n          <marker id=\\"timeline-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Forecasting vocabulary on one timeline</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">Everything to the left of the origin is known. Everything to the right must be predicted or known in advance.</text>\\n\\n        <line x1=\\"70\\" y1=\\"148\\" x2=\\"910\\" y2=\\"148\\" stroke=\\"#d0d7de\\" stroke-width=\\"3\\"></line>\\n        <g fill=\\"#eaf3ff\\" stroke=\\"#0969da\\">\\n          <rect x=\\"110\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n          <rect x=\\"194\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n          <rect x=\\"278\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n          <rect x=\\"362\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n        </g>\\n        <g fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\">\\n          <rect x=\\"530\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n          <rect x=\\"614\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n          <rect x=\\"698\\" y=\\"122\\" width=\\"66\\" height=\\"52\\" rx=\\"10\\"></rect>\\n        </g>\\n        <line x1=\\"475\\" y1=\\"92\\" x2=\\"475\\" y2=\\"204\\" stroke=\\"#8250df\\" stroke-width=\\"3\\"></line>\\n        <text x=\\"475\\" y=\\"84\\" class=\\"label\\" text-anchor=\\"middle\\">forecast origin</text>\\n        <text x=\\"269\\" y=\\"102\\" class=\\"label\\" text-anchor=\\"middle\\">lookback window T</text>\\n        <text x=\\"647\\" y=\\"102\\" class=\\"label\\" text-anchor=\\"middle\\">horizon H</text>\\n        <path fill=\\"none\\" d=\\"M110 192 L428 192\\" stroke=\\"#0969da\\" stroke-width=\\"2.4\\" marker-end=\\"url(#timeline-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M530 192 L764 192\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.4\\" marker-end=\\"url(#timeline-arrow)\\"></path>\\n        <text x=\\"143\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-3]</text>\\n        <text x=\\"227\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-2]</text>\\n        <text x=\\"311\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-1]</text>\\n        <text x=\\"395\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">x[t]</text>\\n        <text x=\\"563\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">t+1</text>\\n        <text x=\\"647\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">t+2</text>\\n        <text x=\\"731\\" y=\\"154\\" class=\\"label\\" text-anchor=\\"middle\\">t+3</text>\\n      </svg>\\n      <figcaption>\\n        Forecasting is not \u201cpredict any random held-out row.\u201d It is \u201cstand at an origin and predict what comes after it.\u201d\\n      </figcaption>\\n    </figure>\\n\\n    <h2 id=\\"5-turning-a-long-series-into-supervised-learning-windows\\">5) Turning a long series into supervised learning windows</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A model such as linear regression expects input-output pairs. A raw time series is one long ordered list.\\n        Windowing converts the long list into many supervised examples.\\n      </p>\\n      <p>\\n        If the full series has length \\\\(L\\\\) and you use lookback \\\\(T\\\\) to predict the next value, the number of one-step\\n        training windows is:\\n      </p>\\n      <p style=\\"font-size:1.05rem;\\">\\n        \\\\[\\n          \\\\text{windows} = L - (T+1) + 1 = L - T\\n        \\\\]\\n      </p>\\n      <p class=\\"mini\\">\\n        Why \\\\(T+1\\\\)? Because each supervised example needs \\\\(T\\\\) input values plus one target value.\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Raw series</th>\\n            <th>Lookback \\\\(T=3\\\\)</th>\\n            <th>Target</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr><td>[10, 12, 13, 15, 18, 20]</td><td>[10, 12, 13]</td><td>15</td></tr>\\n          <tr><td>[10, 12, 13, 15, 18, 20]</td><td>[12, 13, 15]</td><td>18</td></tr>\\n          <tr><td>[10, 12, 13, 15, 18, 20]</td><td>[13, 15, 18]</td><td>20</td></tr>\\n        </tbody>\\n      </table>\\n\\n      <pre><code class=\\"language-python\\">import numpy as np\\n\\ndef make_supervised_1d(series: np.ndarray, lookback: int):\\n    \\"\\"\\"\\n    Converts a 1D time series into supervised learning data:\\n      X[i] = series[i : i+lookback]\\n      y[i] = series[i+lookback]\\n    \\"\\"\\"\\n    series = np.asarray(series, dtype=np.float32)\\n    L = len(series)\\n    if L &lt;= lookback:\\n        raise ValueError(\\"series is too short for the chosen lookback\\")\\n\\n    X = []\\n    y = []\\n    for i in range(L - lookback):\\n        X.append(series[i : i + lookback])\\n        y.append(series[i + lookback])\\n    return np.stack(X), np.asarray(y)\\n\\nx = np.arange(10, dtype=np.float32)  # [0..9]\\nX, y = make_supervised_1d(x, lookback=3)\\nprint(X.shape, y.shape)  # (7, 3) (7,)</code></pre>\\n    </div>\\n\\n    <h2 id=\\"6-a-dumb-but-great-baseline-linear-regression-as-an-ar-model\\">6) A \u201cdumb but great\u201d baseline: linear regression as an AR model</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Before you reach for RNNs, use a simple baseline. For a 1D time series (\\\\(D=1\\\\)), treat the previous \\\\(p\\\\) values\\n        as features and use linear regression.\\n      </p>\\n\\n      <p style=\\"font-size:1.05rem;\\">\\n        \\\\[\\n          \\\\hat{x}_t = w_0 + w_1 x_{t-1} + w_2 x_{t-2} + \\\\dots + w_p x_{t-p}\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        In statistics this is an <strong>autoregressive (AR)</strong> model: the series is predicted from its own past.\\n        In ML language, it is a supervised learning model built from lag features.\\n      </p>\\n    </div>\\n\\n    <div class=\\"grid\\">\\n      <div class=\\"card\\">\\n        <h3 id=\\"persistence-baseline\\">Persistence baseline</h3>\\n        <p>\\n          The simplest forecast is \\\\(\\\\hat{x}_{t+1}=x_t\\\\): tomorrow equals today. This is surprisingly hard to beat for\\n          some noisy series and should be your first sanity check.\\n        </p>\\n      </div>\\n      <div class=\\"card\\">\\n        <h3 id=\\"seasonal-naive-baseline\\">Seasonal naive baseline</h3>\\n        <p>\\n          If the series repeats every \\\\(s\\\\) steps, forecast \\\\(\\\\hat{x}_{t+1}=x_{t+1-s}\\\\). For hourly daily seasonality,\\n          \\\\(s=24\\\\); for daily weekly seasonality, \\\\(s=7\\\\).\\n        </p>\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"7-exogenous-variables-what-is-known-in-the-future\\">7) Exogenous variables: what is known in the future?</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Many forecasts use extra features besides the target\u2019s own past. These are often called <strong>exogenous variables</strong>\\n        or covariates.\\n      </p>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Feature type</th>\\n            <th>Examples</th>\\n            <th>Can you use it for future horizons?</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Known in advance</td>\\n            <td>day of week, holidays, planned price, calendar month</td>\\n            <td>Yes, if it is truly known at forecast time.</td>\\n          </tr>\\n          <tr>\\n            <td>Observed only later</td>\\n            <td>future sales, future weather observations, future demand, future sensor values</td>\\n            <td>No, unless you separately forecast it first or use a scenario.</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n      <div class=\\"callout tight\\">\\n        <p>\\n          <strong>Leakage rule:</strong> every input feature for a forecast horizon must be information you would actually have at the forecast origin.\\n        </p>\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"8-the-most-common-forecasting-mistake-leaking-future-inputs\\">8) The most common forecasting mistake: leaking future inputs</h2>\\n    <div class=\\"callout\\">\\n      <p><strong>The wrong way for multi-step forecasting:</strong></p>\\n      <p>\\n        Predicting day 5 using inputs that include the <em>true</em> day 4 value, when day 4 is not known at forecast time.\\n        This makes the plot look nice but it is not a valid multi-step forecast.\\n      </p>\\n    </div>\\n\\n    <div class=\\"ok\\">\\n      <p><strong>The correct recursive / rolling forecast:</strong></p>\\n      <p>\\n        When you need multiple steps ahead, feed the model\u2019s <strong>own previous predictions</strong> back as inputs.\\n        This matches reality: once you step into the future, you no longer have ground-truth observations.\\n      </p>\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 310\\" role=\\"img\\" aria-label=\\"Recursive forecasting diagram\\">\\n        <defs>\\n          <marker id=\\"recursive-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Recursive multi-step forecasting</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">After the first future step, the model must consume its own predictions, not hidden true values.</text>\\n\\n        <g transform=\\"translate(44,104)\\">\\n          <text x=\\"110\\" y=\\"-14\\" class=\\"label\\" text-anchor=\\"middle\\">known history</text>\\n          <rect x=\\"0\\" y=\\"22\\" width=\\"68\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"84\\" y=\\"22\\" width=\\"68\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"168\\" y=\\"22\\" width=\\"68\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <text x=\\"34\\" y=\\"49\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-2]</text>\\n          <text x=\\"118\\" y=\\"49\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-1]</text>\\n          <text x=\\"202\\" y=\\"49\\" class=\\"label\\" text-anchor=\\"middle\\">x[t]</text>\\n        </g>\\n\\n        <rect x=\\"340\\" y=\\"126\\" width=\\"120\\" height=\\"58\\" rx=\\"13\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n        <text x=\\"400\\" y=\\"160\\" class=\\"label\\" text-anchor=\\"middle\\">AR model</text>\\n        <rect x=\\"548\\" y=\\"126\\" width=\\"96\\" height=\\"58\\" rx=\\"13\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n        <text x=\\"596\\" y=\\"160\\" class=\\"label\\" text-anchor=\\"middle\\">xhat[t+1]</text>\\n        <rect x=\\"722\\" y=\\"126\\" width=\\"96\\" height=\\"58\\" rx=\\"13\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n        <text x=\\"770\\" y=\\"160\\" class=\\"label\\" text-anchor=\\"middle\\">xhat[t+2]</text>\\n\\n        <path fill=\\"none\\" d=\\"M280 148 L340 148 M460 155 L548 155 M644 155 L722 155\\" stroke=\\"#0969da\\" stroke-width=\\"2.4\\" marker-end=\\"url(#recursive-arrow)\\"></path>\\n        <path d=\\"M596 184 C548 245 208 245 160 170\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.3\\" fill=\\"none\\" marker-end=\\"url(#recursive-arrow)\\"></path>\\n        <text x=\\"350\\" y=\\"270\\" class=\\"muted\\" text-anchor=\\"middle\\">slide the window: drop oldest, append prediction, repeat until horizon H</text>\\n      </svg>\\n      <figcaption>\\n        This is the same autoregressive idea that later appears in language generation: predicted outputs become part of the next input context.\\n      </figcaption>\\n    </figure>\\n\\n    <h2 id=\\"9-forecasting-strategies-for-h-1\\">9) Forecasting strategies for \\\\(H&gt;1\\\\)</h2>\\n    <div class=\\"card\\">\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Strategy</th>\\n            <th>How it works</th>\\n            <th>Tradeoff</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Recursive</td>\\n            <td>Train one-step model; roll it forward by feeding predictions back in.</td>\\n            <td>Simple and uses all one-step data, but errors compound.</td>\\n          </tr>\\n          <tr>\\n            <td>Direct</td>\\n            <td>Train a separate model for each horizon step: one for \\\\(t+1\\\\), one for \\\\(t+2\\\\), etc.</td>\\n            <td>Avoids recursive feedback, but needs more models and less data per horizon.</td>\\n          </tr>\\n          <tr>\\n            <td>Multi-output</td>\\n            <td>Train one model to output all \\\\(H\\\\) future steps at once.</td>\\n            <td>Can learn horizon relationships, but the output layer and loss must match the forecast task.</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n      <p>\\n        Chapter 9 focuses on the recursive version because it exposes the core forecasting issue most clearly: after the origin,\\n        real future observations are unavailable.\\n      </p>\\n    </div>\\n\\n    <h2 id=\\"10-minimal-correct-forecasting-code-baseline-ar-with-recursion\\">10) Minimal, correct forecasting code: baseline AR with recursion</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"train-a-linear-model-scikit-learn-style-and-forecast-recursively\\">Train a linear model (scikit-learn style) and forecast recursively</h3>\\n      <pre><code class=\\"language-python\\">import numpy as np\\nfrom sklearn.linear_model import LinearRegression\\n\\ndef fit_ar_linear(train_series: np.ndarray, lookback: int) -&gt; LinearRegression:\\n    X_train, y_train = make_supervised_1d(train_series, lookback)\\n    model = LinearRegression()\\n    model.fit(X_train, y_train)\\n    return model\\n\\ndef recursive_forecast_1d(model, history: np.ndarray, lookback: int, horizon: int):\\n    \\"\\"\\"\\n    history: last observed values, at least lookback long.\\n    Returns: horizon predictions [xhat(t+1), xhat(t+2), ...].\\n    \\"\\"\\"\\n    hist = list(np.asarray(history, dtype=np.float32))\\n    if len(hist) &lt; lookback:\\n        raise ValueError(\\"history must contain at least lookback values\\")\\n\\n    preds = []\\n    for _ in range(horizon):\\n        x_in = np.array(hist[-lookback:], dtype=np.float32).reshape(1, -1)\\n        y_hat = float(model.predict(x_in)[0])\\n        preds.append(y_hat)\\n        hist.append(y_hat)  # key step: feed prediction back in\\n    return np.array(preds, dtype=np.float32)\\n\\nseries = np.sin(np.linspace(0, 10*np.pi, 500)).astype(np.float32)\\ntrain, test = series[:400], series[400:]\\n\\nlookback = 20\\nhorizon = 30\\n\\nar = fit_ar_linear(train, lookback=lookback)\\nhistory = train[-lookback:]\\npreds = recursive_forecast_1d(ar, history, lookback=lookback, horizon=horizon)\\n\\nprint(\\"First 5 predictions:\\", preds[:5])</code></pre>\\n\\n      <div class=\\"callout tight\\">\\n        <p>\\n          <strong>Important:</strong> this evaluates a real forecast. After the split point, the model does not receive true future target values as inputs.\\n        </p>\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"11-evaluation-one-split-is-a-start-backtesting-is-better\\">11) Evaluation: one split is a start, backtesting is better</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A single chronological train/test split is better than random splitting, but it can still be lucky or unlucky.\\n        In production forecasting, you often use <strong>walk-forward backtesting</strong>: choose several forecast origins,\\n        forecast the next \\\\(H\\\\) steps from each origin, and aggregate the errors.\\n      </p>\\n      <ul>\\n        <li><strong>MAE:</strong> average absolute error; easy to interpret in original units.</li>\\n        <li><strong>RMSE:</strong> penalizes large errors more strongly.</li>\\n        <li><strong>MAPE:</strong> percentage error; fragile when true values are near zero.</li>\\n        <li><strong>MASE / scaled error:</strong> compares against a naive baseline, useful across series with different scales.</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"12-where-rnns-fit-next\\">12) Where RNNs fit next</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        This tutorial intentionally starts with the simplest correct approach: an autoregressive baseline. RNNs and later\\n        sequence models help when relationships are nonlinear, depend on longer context, or involve high-dimensional inputs.\\n      </p>\\n      <p>\\n        Chapter 10 replaces a fixed lookback vector with recurrent hidden state. It then uses translation to show the same\\n        step-by-step idea in text: tokens become embeddings, a decoder produces one output at a time, and autoregressive\\n        decoding feeds previous outputs back into the next step.\\n      </p>\\n      <p>\\n        The data-shape thinking (\\\\(N \\\\times T \\\\times D\\\\)) and the \u201cno future leakage\u201d rule remain the same no matter how\\n        sophisticated the model becomes.\\n      </p>\\n      <p class=\\"mini\\">\\n        If the baseline evaluation is wrong, you cannot trust the advanced model evaluation either.\\n      </p>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"checklist-a-correct-forecasting-setup\\">Checklist: a correct forecasting setup</h3>\\n      <ul>\\n        <li><strong>Define the horizon \\\\(H\\\\)</strong>: one-step prediction and multi-step forecasting are different tasks.</li>\\n        <li><strong>Choose the lookback \\\\(T\\\\)</strong>: enough context to model the pattern without unnecessary noise.</li>\\n        <li><strong>Split by time</strong>: train on the past, validate/test on the future.</li>\\n        <li><strong>Fit preprocessing on training only</strong>: scaling, imputation, feature selection, and hyperparameters must not see the future period.</li>\\n        <li><strong>No leakage</strong>: future target values cannot be used as future inputs.</li>\\n        <li><strong>Start with baselines</strong>: persistence, seasonal naive, and AR/linear regression before complex sequence models.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Chapter transition</strong>\\n      With the forecasting contract, baselines, and leakage-safe evaluation in\\n      place, the next chapter implements the autoregressive linear baseline in\\n      PyTorch before recurrent state is introduced.\\n    </div>\\n  </main>"}'),l={title:"Forecasting and Sequence Data (Time Series)",slug:"/part5-deep-learning-and-llms/08-forecasting-sequence-data",description:"A standalone tutorial on what sequence data is, how to shape it for ML, what \u201cforecasting\u201d really means, and how to avoid the most common multi-step forecasting mistake: data leakage through future inputs.",sidebar_label:"8. Forecasting and sequence data",pagination_label:"8. Forecasting and sequence data",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},h=[];function u(e){return(0,s.jsx)(i.A,{content:o})}function p(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u()}}}]);